namespace kstation {
// Produces replies for current-patch and global dumps; UART enqueue and patch
// packing are named children so their exact scheduling stays with the board.
class ControllerMidiSysExReplyTask final {
 using C=MidiSysExDumpCurrentTask;using CS=C::Stage;using G=MidiSysExDumpSystemTask;using GS=G::Stage;using I=MidiSysExIdentityTask;using IS=I::Stage;using H=MidiSysExSendHeaderTask;using HS=H::Stage;using B=MidiSysExSendBytesTask;using BS=B::Stage;using U=MidiSysExUartTask;using US=U::Stage;using Q=ArpMidiEnqueueTask;using QS=Q::Stage;using K=MidiSysExDumpBankReplyTask;using KS=K::Stage;using A=MidiSysExDumpAddressTask;using AS=A::Stage;
public:
 enum class Kind:uint8_t{Current,Global,Patch,Performance};enum class Service:uint8_t{None,RefreshPatch,EnqueueByte,UnsupportedPack};struct Request{Service service=Service::None;uint8_t byte=0;};
 explicit ControllerMidiSysExReplyTask(Kind k,uint8_t command=0,uint8_t section=0,uint8_t index=0):kind_(k),command_(command),section_(section),index_(index){if(k==Kind::Current)current_.emplace();else if(k==Kind::Global)global_.emplace();else bank_.emplace(k==Kind::Patch?K::Kind::Patch:K::Kind::Performance);}
 bool complete()const{return done_;}
 Request request()const{if(patchPack_)return {patchPack_->unsupportedTarget()?Service::UnsupportedPack:Service::None,0};if(queue_)return {};if(uart_&&uart_->awaitingChild())return {Service::EnqueueByte,byte_};if(current_&&current_->awaitingChild()&&current_->child()==C::Child::Refresh&&!identity_&&!header_&&!bytes_&&!uart_)return {Service::RefreshPatch,0};return {};}
 bool resume(Service s){if(s==Service::None||request().service!=s)return false;return s==Service::EnqueueByte?uart_->resume():current_->resume(C::Child::Refresh);}
 ControllerFlashProgramTask::MaskAction maskAction()const{if(!queue_)return ControllerFlashProgramTask::MaskAction::None;auto s=queue_->stage();return s==QS::SaveMask?ControllerFlashProgramTask::MaskAction::Save:s==QS::Mask?ControllerFlashProgramTask::MaskAction::Disable:s==QS::RestoreMask?ControllerFlashProgramTask::MaskAction::Restore:ControllerFlashProgramTask::MaskAction::None;}bool stackWrites()const{if(patchPack_)return patchPack_->stackWrites();if(queue_){auto s=queue_->stage();return s==QS::SaveFirst||s==QS::SaveSecond;}if(uart_){auto s=uart_->stage();return s==US::Save||s==US::Enqueue;}if(bytes_)return bytes_->stage()==BS::Send;if(header_)return header_->stage()==HS::SendStart||header_->stage()==HS::SendIdentity;if(identity_)return false;if(address_)return address_->stage()==AS::Identity;if(bank_){auto s=bank_->stage();return s==KS::Address||s==KS::Header||s==KS::SendData;}if(current_){auto s=current_->stage();return s==CS::Refresh||s==CS::Identity||s==CS::Header||s==CS::SendData||s==CS::SendEnd;}auto s=global_->stage();return s==GS::Identity||s==GS::Header||s==GS::SendData||s==GS::SendEnd;}
 unsigned nextClocks(int previous=-1)const{if(done_||request().service!=Service::None)return 0;if(patchPack_)return patchPack_->nextClocks(previous);if(queue_){switch(queue_->stage()){case QS::SaveFirst:case QS::SaveSecond:case QS::RestoreFirst:case QS::RestoreSecond:return 10;case QS::ReadProducer:case QS::ReadConsumer:return 12;case QS::BindRing:return 9;case QS::WriteData:return 3+bus(queue_->address(),previous);case QS::MaskIndex:return 6;case QS::WriteProducer:return 9+bus(0xc492,previous);case QS::WriteEnable:return 4;case QS::Return:return 7;case QS::Complete:return 0;default:return 3;}}if(uart_){switch(uart_->stage()){case US::Save:case US::Restore:return 6;case US::Enqueue:return 10;case US::Return:return 7;case US::AwaitChild:case US::Complete:return 0;default:return 3;}}if(bytes_){switch(bytes_->stage()){case BS::Read:return 5+bus(bytes_->source(),-1);case BS::Send:return 10;case BS::Return:return 7;case BS::AwaitChild:case BS::Complete:return 0;default:return 3;}}if(header_){switch(header_->stage()){case HS::SendStart:return 10;case HS::BindSource:return 9;case HS::BindCount:return 6;case HS::SendIdentity:return 5;case HS::Return:return 7;case HS::AwaitChild:case HS::Complete:return 0;default:return 3;}}if(identity_){switch(identity_->stage()){case IS::BindDestination:case IS::BindSource:return 9;case IS::BindCount:return 6;case IS::Read:return 5+bus(identity_->source(),-1);case IS::Write:return 3+bus(identity_->destination(),previous);case IS::Return:return 7;case IS::Complete:return 0;default:return 3;}}if(address_){switch(address_->stage()){case AS::Identity:return 10;case AS::WriteCommand:case AS::WriteSection:case AS::WriteIndex:return 9+bus(address_->stage()==AS::WriteCommand?0xcd21:address_->stage()==AS::WriteSection?0xcd24:0xcd25,previous);case AS::ScaleBank:case AS::ScaleIndex:return 6;case AS::MultiplyBank:case AS::MultiplyIndex:return 23;case AS::AddBase:return 9;case AS::Return:return 7;case AS::AwaitChild:case AS::Complete:return 0;default:return 3;}}if(bank_){switch(bank_->stage()){case KS::Address:return 5;case KS::WriteType:return 9+bus(0xcd20,previous);case KS::Header:case KS::SendData:return 10;case KS::BindCount:return 6;case KS::SendEnd:return 8;case KS::AwaitChild:case KS::Complete:return 0;default:return 3;}}if(current_){switch(current_->stage()){case CS::Refresh:case CS::SendEnd:return 10;case CS::Identity:case CS::Header:case CS::SendData:return 5;case CS::WriteType:return 9+bus(0xcd20,previous);case CS::BindSource:return 9;case CS::BindCount:return 6;case CS::Return:return 7;case CS::AwaitChild:case CS::Complete:return 0;default:return 3;}}switch(global_->stage()){case GS::Identity:case GS::Header:case GS::SendData:case GS::SendEnd:return 10;case GS::WriteType:return 9+bus(0xcd20,previous);case GS::BindSource:return 9;case GS::BindCount:return 6;case GS::Return:return 7;case GS::AwaitChild:case GS::Complete:return 0;default:return 3;}}
 template<class R,class W>unsigned advanceBefore(unsigned budget,R&&read,W&&write,int previous=-1){auto cost=nextClocks(previous);if(!cost||cost>budget)return 0;
  if(patchPack_){auto n=patchPack_->advanceBefore(cost,read,write,previous);if(patchPack_->complete()){patchPack_.reset();current_->resume(C::Child::Refresh);}return n;}if(queue_){queue_->advance([&](Q::Read f){return uint16_t(read(f==Q::Read::Producer?0xc492:0xc494,2,cost));},[&](Q::Write f,uint32_t v){write(f==Q::Write::Data?queue_->address():f==Q::Write::Producer?0xc492:0xffffb2,v,f==Q::Write::Producer?2:1,cost);});if(queue_->complete()){queue_.reset();uart_->resume();}return cost;}if(uart_){uart_->advance();if(uart_->awaitingChild())queue_.emplace(byte_);if(uart_->complete()){uart_.reset();if(bytes_)bytes_->resume();else if(header_)header_->resume(H::Child::SendStart);else if(bank_){bank_->resume(K::Child::SendEnd);done_=bank_->complete();}else if(current_)current_->resume(C::Child::SendEnd);else global_->resume(G::Child::SendEnd);}return cost;}
  if(bytes_){bytes_->advance([&](uint32_t a){return uint8_t(read(a,1,cost-2));});if(bytes_->awaitingChild()){byte_=bytes_->value();uart_.emplace();}if(bytes_->complete()){bytes_.reset();if(header_)header_->resume(H::Child::SendIdentity);else if(bank_)bank_->resume(K::Child::SendData);else if(current_)current_->resume(C::Child::SendData);else global_->resume(G::Child::SendData);}return cost;}
  if(header_){header_->advance();if(header_->awaitingChild()){if(header_->child()==H::Child::SendStart){byte_=0xf0;uart_.emplace();}else bytes_.emplace(0xcd1a,12);}if(header_->complete()){header_.reset();if(bank_)bank_->resume(K::Child::Header);else if(current_)current_->resume(C::Child::Header);else global_->resume(G::Child::Header);}return cost;}
  if(identity_){identity_->advance([&](uint32_t a){return uint8_t(read(a,1,cost-2));},[&](uint32_t a,uint8_t v){write(a,v,1,cost);});if(identity_->complete()){identity_.reset();if(address_)address_->resume();else if(current_)current_->resume(C::Child::Identity);else global_->resume(G::Child::Identity);}return cost;}
  if(address_){address_->advance([&](A::Write f,uint8_t v){write(f==A::Write::Command?0xcd21:f==A::Write::Section?0xcd24:0xcd25,v,1,cost);});if(address_->awaitingChild())identity_.emplace();if(address_->complete()){bankSource_=address_->address();address_.reset();bank_->resume(K::Child::Address);}return cost;}
  if(bank_){bank_->advance([&](uint8_t v){write(0xcd20,v,1,cost);});if(bank_->awaitingChild()){auto c=bank_->child();if(c==K::Child::Address)address_.emplace(command_,section_,index_);else if(c==K::Child::Header)header_.emplace();else if(c==K::Child::SendData)bytes_.emplace(bankSource_,kind_==Kind::Patch?128:256);else {byte_=0xf7;uart_.emplace();}}done_=bank_->complete();return cost;}
  if(current_){current_->advance([&](){write(0xcd20,0,1,cost);});if(current_->awaitingChild()){auto c=current_->child();if(c==C::Child::Refresh)patchPack_.emplace();else if(c==C::Child::Identity)identity_.emplace();else if(c==C::Child::Header)header_.emplace();else if(c==C::Child::SendData)bytes_.emplace(0xba5c,128);else if(c==C::Child::SendEnd){byte_=0xf7;uart_.emplace();}}done_=current_->complete();return cost;}
  global_->advance([&](){write(0xcd20,3,1,cost);});if(global_->awaitingChild()){auto c=global_->child();if(c==G::Child::Identity)identity_.emplace();else if(c==G::Child::Header)header_.emplace();else if(c==G::Child::SendData)bytes_.emplace(0x21ff00,256);else if(c==G::Child::SendEnd){byte_=0xf7;uart_.emplace();}}done_=global_->complete();return cost;
 }
private:static unsigned bus(uint32_t a,int p){a&=0xffffff;if(a<0x400000||(a>=0xfffd10&&a<0xffffa0))return (p&1)||a!=uint32_t(p|1)?(a<0x400000?3:1):0;return a>=0xffffa0?1:3;}Kind kind_;bool done_=false;uint8_t byte_=0,command_=0,section_=0,index_=0;uint32_t bankSource_=0;std::optional<C>current_{};std::optional<G>global_{};std::optional<I>identity_{};std::optional<H>header_{};std::optional<B>bytes_{};std::optional<U>uart_{};std::optional<Q>queue_{};std::optional<K>bank_{};std::optional<A>address_{};std::optional<ControllerPatchPackTask>patchPack_{};
};
}
